local a=require"system.util"local b=require"system.filesystem"local c=assert(a.argparse({h=false,H=false,L=false,P=false,R=false},...))if#c<2 then error("usage: chown [-h] [-R [-H|-L|-P]] <owner> <file...>")end;local function d(e,f)b.chown(e,f)if b.stat(e,true).type=="directory"then for g,h in ipairs(b.list(e))do d(b.combine(e,h),f)end end end;local f=c[1]:gsub(":.*","")for i=2,#c do if c.R then d(c[i],f)else b.chown(c[i],f)end end
